harness_source:
use hawdb_core::{PropertyType, Value};
use hawdb_executor::{numeric::{NumericFragment, retained::{RetainedNumericBuilder, RetainedNumericValues}}, NumericLiteral, NumericPredicate, QueryMemoryClass, QueryMemoryLedger};
use hawdb_qos::{IoConcurrencyBudget, RuntimeGovernor, RuntimeGovernorConfig, RuntimeResourceSnapshot, RuntimeWorkRequest};
use hawdb_storage::{NodeId, NodeRecord};
use std::{collections::{BTreeMap, BTreeSet}, hint::black_box, num::NonZeroUsize, time::Instant};
fn nz(n: usize) -> NonZeroUsize { NonZeroUsize::new(n).unwrap() }
fn main() {
 let args: Vec<_> = std::env::args().collect();
 let width: usize = args[1].parse().unwrap();
 let rounds: usize = args[2].parse().unwrap();
 let property = format!("property-{:04}", width / 2);
 let node = NodeRecord { id: NodeId(1), labels: BTreeSet::new(), properties: (0..width).map(|i| (format!("property-{i:04}"), Value::Int(i as i64))).collect::<BTreeMap<_,_>>() };
 let fragment = NumericFragment { label: "Item", property: &property, property_type: PropertyType::Int, predicate: NumericPredicate::Eq, expected: NumericLiteral::Int((width/2) as i64), fused_operators: None };
 let governor = RuntimeGovernor::new(RuntimeGovernorConfig::shared_host(), RuntimeResourceSnapshot::detect(), IoConcurrencyBudget::new(2,1));
 let permit = governor.try_admit(RuntimeWorkRequest::foreground_query(0,65536)).unwrap();
 let ledger = QueryMemoryLedger::new(nz(65536));
 let account = ledger.account(QueryMemoryClass::ResultMaterialization,"probe",nz(65536));
 let mut elapsed = 0u128;
 let mut peak = 0;
 for _ in 0..rounds {
  let mut builder = RetainedNumericBuilder::new(fragment,nz(1024),false,account.clone(),&permit).unwrap();
  let start = Instant::now();
  for _ in 0..1024 { builder.push_node(black_box(&node)).unwrap(); }
  elapsed += start.elapsed().as_nanos();
  let batch = builder.seal(None).unwrap();
  assert_eq!(batch.selected_rows().0.len(),1024);
  match batch.values().0 { RetainedNumericValues::Int(values) => assert!(values.iter().all(|v| *v==(width/2) as i64)), _ => panic!("unexpected type") };
  peak = peak.max(ledger.snapshot().peak_bytes);
  black_box(&batch);
 }
 assert_eq!(ledger.snapshot().used_bytes,0);
 assert_eq!(governor.retained_result_snapshot().retained_bytes,0);
 println!("{}",serde_json::json!({"width":width,"rounds":rounds,"rows":rounds*1024,"extract_ns":elapsed,"ledger_peak_bytes":peak,"released_bytes":ledger.snapshot().used_bytes,"scope":"isolated retained push_node CPU; not full-query performance acceptance"}));
}

